var cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
var results = [];
for (var i = 0; i < Math.min(cards.length, 8); i++) {
  var card = cards[i];
  var title = card.querySelector('span[class*="title"], .card__title, span');
  var ratingEl = card.querySelector('[id*="recipe-star-rating"]');
  var starCount = 0;
  if (ratingEl) {
    var stars = ratingEl.querySelectorAll('svg');
    stars.forEach(function(s) {
      // Check parent or self for fill
      var html = s.outerHTML + ' ' + (s.parentElement ? s.parentElement.outerHTML : '');
      if (html.includes('icon-star ') && !html.includes('icon-star-half')) {
        // Determine if filled
        var useEl = s.querySelector('use');
        if (useEl) {
          starCount++;
        }
      }
    });
  }
  // Better approach - look at the rating number value
  var ratingNumEl = card.querySelector('.mm-recipes-star-rating__rating-number, [class*="rating"]');
  var href = card.href;
  // Get all the text
  var fullText = card.textContent.replace(/\s+/g, ' ').trim();
  results.push({
    title: (title ? title.textContent.trim() : ''),
    href: href,
    fullText: fullText.substring(0, 200),
    starIcons: ratingEl ? ratingEl.querySelectorAll('svg').length : 0
  });
}
return results;

var ratingEls = document.querySelectorAll('[id*="recipe-star-rating"]');
var results = [];
ratingEls.forEach(function(el, idx) {
  var svgs = el.querySelectorAll('svg');
  var filledCount = 0;
  var halfCount = 0;
  svgs.forEach(function(s) {
    var cls = s.getAttribute('class') || '';
    var useEl = s.querySelector('use');
    var href = useEl ? useEl.getAttribute('xlink:href') : '';
    // Check parent classes
    var parentCls = s.parentElement ? s.parentElement.getAttribute('class') : '';
    if (cls.includes('star')) {
      // Check if it's a half-star or full-star vs empty
      if (cls.includes('star-half') || parentCls.includes('star-half')) {
        halfCount++;
      } else if (cls.includes('star-empty') || parentCls.includes('star-empty')) {
        // empty
      } else {
        filledCount++;
      }
    }
  });
  // Look at surrounding context for title
  var card = el.closest('a[id*="card-list-card"]');
  var titleEl = card ? card.querySelector('span[class*="title"]') : null;
  // Get the title from card link text
  var cardText = card ? card.textContent.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() : '';
  results.push({
    idx: idx,
    filled: filledCount,
    half: halfCount,
    svgClasses: Array.from(svgs).map(function(s){return s.getAttribute('class');}).join('|'),
    cardTitle: cardText.substring(0, 100)
  });
});
return results;

