function ratingFor(id) {
  const el = document.querySelector(`#mntl-recipe-star-rating_${id}-0`);
  if (!el) return null;
  // Each star SVG, take its visible width to estimate the rating
  const svgs = Array.from(el.querySelectorAll('svg'));
  let rating = 0;
  for (const svg of svgs) {
    const rect = svg.getBoundingClientRect();
    // SVG icons typically use viewBox 0 0 24 24; full star ~24px wide
    // Get the width of the filled portion (inner fill or clip)
    const fill = svg.querySelector('.fill, .filled, [class*="fill"]');
    let fillRatio = 1;
    if (fill) {
      const fr = fill.getBoundingClientRect();
      fillRatio = rect.width ? fr.width / rect.width : 1;
    } else {
      // Look for mask or clip
      const rects = svg.querySelectorAll('rect, path');
      // Heuristic: if there's a half-width rect, it's a half star
      for (const r of rects) {
        const w = r.getAttribute('width');
        if (w && !isNaN(parseFloat(w))) {
          const ratio = parseFloat(w) / 24;
          if (ratio > 0 && ratio < 1) { fillRatio = ratio; break; }
        }
      }
    }
    rating += fillRatio;
  }
  return Math.round(rating * 10) / 10;
}
