// Look at parent div width of star-rating container - it may use overflow to show partial fills
const starRatings = document.querySelectorAll('[id^="mntl-recipe-star-rating_"]');
const results = [];
starRatings.forEach(el => {
  const elStyle = window.getComputedStyle(el);
  const rect = el.getBoundingClientRect();
  // Check parent for overflow
  const parent = el.parentElement;
  const parentStyle = window.getComputedStyle(parent);
  const grandParent = parent.parentElement;
  const grandParentStyle = window.getComputedStyle(grandParent);
  // Look for partial star technique
  const inner = el.innerHTML;
  // Try to find any numeric data attributes
  const dataAttrs = {};
  Array.from(el.attributes).forEach(a => dataAttrs[a.name] = a.value);
  results.push({
    width: rect.width,
    innerSnippet: inner.slice(0, 200),
    dataAttrs,
    parentClass: parent.className,
    parentStyleOverflow: parentStyle.overflow,
    grandParentStyleOverflow: grandParentStyle.overflow,
  });
});
return results.slice(0, 5);

